"""Record exact primary status deltas; no refreshed clinical/funding dates."""
from daily20 import ROOT,RUN,read,write,now,attempts
import collections
b={r['id']:r for r in read(RUN/'before-trials_base.json')};c={r['id']:r for r in read(ROOT/'data/trials_base.json')};aa=attempts();changes=[]
for tid in ['elias-eci-chemo-osa','csu-cotc033-vaccine-immunity','osu-probiome-bladder']:
 assert b[tid].get('verified')==c[tid].get('verified') and b[tid].get('funding_verified')==c[tid].get('funding_verified')
 changes.append({'trial_id':tid,'before':b[tid],'after':c[tid],'clinical_and_funding_dates_retained':True,'actual_evidence':[a for a in aa if a['source_id'] in {'sponsor-elias-clinical-studies','registry:cotc033','registry:probiome','protocol:csu-cotc033-vaccine-immunity','usa-missouri-oncology-clinical-trials'}], 'clinical_criteria_full_review_today':False})
write(RUN/'status-reconciliation.json',{'run_id':RUN.name,'decision_at':now(),'changes':changes,'newly_hidden_public_ids':['elias-eci-chemo-osa','csu-cotc033-vaccine-immunity'],'already_hidden_status_correction_ids':['osu-probiome-bladder'],'whole_historical_registry_site_reconciliation':{'COTC033':['CSU Fort Collins: finished recruiting in current direct public protocol','Wisconsin Madison: registry historical site; not added as current','OhioState Columbus: registry historical site; not added as current','Georgia Athens: registry historical site; not added as current','Missouri Columbia: current primary still enrolling; conflict retained under owner AVMA Completed decision'],'Probiome':['Georgia Athens','NCState Raleigh','OhioState Columbus']},'ELIAS_scope':'Exact ECI-plus-chemotherapy trial closed. Separate previously closed ECIP-OSA-01 and commercial ECI not conflated. Known denied direct protocol not requested.','independent_cases':[{'trial_id':tid,'name':name,'patient':{'species':'Dog','country':'USA','cancer':diagnosis},'expected':'exclude'} for tid,diagnosis in [('elias-eci-chemo-osa','Osteosarcoma'),('csu-cotc033-vaccine-immunity','Soft tissue sarcoma'),('osu-probiome-bladder','Urothelial / transitional cell carcinoma')] for name in ['source-compatible diagnosis cannot override closed enrollment','unknown eligibility cannot restore closed enrollment']]+[{'trial_id':tid,'name':'Browse cannot resurrect closed study','patient':{'species':'Dog','country':'USA','cancer':'Cancer — any type'},'expected':'exclude'} for tid in ['elias-eci-chemo-osa','csu-cotc033-vaccine-immunity','osu-probiome-bladder']]})
print('STATUS_RECONCILIATION',len(changes),'newly_hidden',sum(b[t].get('available_for_matching',False) and not c[t].get('available_for_matching',False) for t in b))
